package com.ias.ticket;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

/** Durable metadata and immutable closed-round projection. Never changes original submission time. */
@RestController
public class Rounds {
 final Tickets t;
 public Rounds(Tickets t){this.t=t;}
 static Instant start(Map<String,Object> row){return Completion.instant(row.getOrDefault("round_started_at",row.get("submitted_at")));}
 static Map<String,Object> activeRule(){
  String configured=System.getenv("IAS_TICKET_SLA_RULE");
  Map<String,Object> rule=configured==null?Map.of("version","SLA_V1","responseMinutes",Map.of("P1",30,"P2",120,"P3",480),"resolutionHours",Map.of("P1",4,"P2",24,"P3",72)):Tickets.json(configured);
  if(!rule.keySet().equals(Set.of("version","responseMinutes","resolutionHours"))||!(rule.get("version") instanceof String s)||!s.matches("[A-Z0-9_-]{1,32}"))throw new Problem(503,"SLA_RULE_UNAVAILABLE");
  for(String key:List.of("responseMinutes","resolutionHours")){if(!(rule.get(key) instanceof Map<?,?> values)||!values.keySet().equals(Set.of("P1","P2","P3")))throw new Problem(503,"SLA_RULE_UNAVAILABLE");for(Object n:values.values())if(!(n instanceof Number)||((Number)n).longValue()<1||((Number)n).longValue()>100000||!n.toString().matches("[1-9][0-9]*"))throw new Problem(503,"SLA_RULE_UNAVAILABLE");}
  return rule;
 }
 static long limit(Map<String,Object> rule,String key,Object priority){return ((Number)((Map<?,?>)rule.get(key)).get(priority.toString())).longValue();}
 Map<String,Object> metadata(Map<String,Object> row){var list=t.db.queryForList("SELECT rd.*,f.snapshot_json frozen_json,f.ended_at FROM ticket_round rd LEFT JOIN ticket_round_freeze f ON f.round_id=rd.id AND f.ticket_id=rd.ticket_id WHERE rd.id=? AND rd.ticket_id=?",row.get("round_id"),row.get("id"));if(list.isEmpty())throw new Problem(503,"ROUND_DATA_INVALID");return list.getFirst();}
 Map<String,Object> rule(Map<String,Object> row){return Tickets.json(metadata(row).get("rule_json"));}
 void initial(String id){var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=?",id);var rule=activeRule();Instant at=Completion.instant(row.get("submitted_at"));String p=row.get("priority").toString();insert(id,id,1,"SUBMISSION",at,null,null,null,null,null,p,rule);t.db.update("UPDATE ticket_record SET round_started_at=submitted_at,policy_version=?,response_due_at=?,resolution_due_at=? WHERE id=?",rule.get("version"),Timestamp.from(at.plusSeconds(limit(rule,"responseMinutes",p)*60)),Timestamp.from(at.plusSeconds(limit(rule,"resolutionHours",p)*3600)),id);}
 void insert(String id,Object ticket,int no,String origin,Instant at,Long by,Object source,Object closure,Object request,Object operation,String priority,Map<String,Object>rule){t.db.update("INSERT INTO ticket_round(id,ticket_id,round_no,origin,started_at,approved_by,source_round_id,source_closure_operation_id,source_request_id,approval_operation_id,priority,rule_version,rule_json,response_ms,resolution_ms) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,ticket,no,origin,Timestamp.from(at),by,source,closure,request,operation,priority,rule.get("version"),Chain.JSON.writeValueAsString(rule),limit(rule,"responseMinutes",priority)*60000,limit(rule,"resolutionHours",priority)*3600000);}
 void freeze(Map<String,Object> row,Instant time){var frozen=new LinkedHashMap<String,Object>();row.forEach((key,value)->frozen.put(key,value instanceof Timestamp||value instanceof LocalDateTime?Tickets.utc(value):value));t.db.update("INSERT INTO ticket_round_freeze(snapshot_json,ended_at,round_id,ticket_id) SELECT ?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM ticket_round_freeze WHERE round_id=?)",Chain.JSON.writeValueAsString(frozen),Timestamp.from(time),row.get("round_id"),row.get("id"),row.get("round_id"));}
 String selected(HttpServletRequest r,Map<String,Object> row){String id=r.getParameter("roundId")==null?row.get("round_id").toString():Tickets.uuid(r.getParameter("roundId"));if(r.getParameterValues("roundId")!=null&&r.getParameterValues("roundId").length!=1)throw Tickets.bad();if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_round WHERE id=? AND ticket_id=?",Long.class,id,row.get("id"))!=1)throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return id;}
 Map<String,Object> selectedRow(Map<String,Object> current,String id){if(current.get("round_id").equals(id))return current;var m=t.db.queryForList("SELECT snapshot_json frozen_json FROM ticket_round_freeze WHERE round_id=? AND ticket_id=?",Tickets.uuid(id),current.get("id"));if(m.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(m.getFirst().get("frozen_json")==null)throw new Problem(503,"ROUND_DATA_INVALID");return Tickets.json(m.getFirst().get("frozen_json"));}
 boolean first(Map<String,Object> row,Tickets.Actor actor,String record,Instant time,String operation){if(t.db.update("UPDATE ticket_record SET first_response_at=?,first_response_actor=?,first_response_record_id=?,first_response_priority=priority WHERE id=? AND round_id=? AND first_response_at IS NULL",Timestamp.from(time),actor.user(),record,row.get("id"),row.get("round_id"))==0)return false;t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,'ROUND_FIRST_RESPONSE',?)",operation,actor.tenant(),actor.user(),Timestamp.from(time));return true;}
 Map<String,Object> metaView(Map<String,Object>m,Map<String,Object>row,boolean current){var out=new LinkedHashMap<String,Object>();out.putAll(Map.of("roundId",m.get("id"),"roundNo",m.get("round_no").toString(),"startedAt",Tickets.utc(m.get("started_at")),"priority",row.get("priority"),"ruleVersion",m.get("rule_version"),"current",current,"status",row.get("status")));out.put("firstResponseAt",row.get("first_response_at")==null?null:Tickets.utc(row.get("first_response_at")));out.put("endedAt",m.get("ended_at")==null?null:Tickets.utc(m.get("ended_at")));out.put("sla",Map.of("responseDueAt",Tickets.utc(row.get("response_due_at")),"resolutionDueAt",Tickets.utc(row.get("resolution_due_at")),"policyVersion",m.get("rule_version"),"confirmationLimitMs",m.get("confirmation_limit_ms").toString(),"supplementLimitMs",m.get("supplement_limit_ms").toString()));return out;}
 void project(Map<String,Object>out,Map<String,Object>row,Object current){var m=metadata(row);out.put("roundNo",m.get("round_no").toString());out.put("roundStartedAt",Tickets.utc(m.get("started_at")));out.put("ruleVersion",m.get("rule_version"));out.put("currentRoundId",current);out.put("isHistorical",!row.get("round_id").equals(current));}
 @GetMapping("/api/ticket/tickets/{id}/rounds") Map<String,Object> history(@PathVariable String id,HttpServletRequest r){var a=t.actor(r,false);var row=t.accessible(id,a);var p=Transfers.page(r,Set.of("page","size"));var list=t.db.queryForList("SELECT rd.*,f.snapshot_json frozen_json,f.ended_at FROM ticket_round rd LEFT JOIN ticket_round_freeze f ON f.round_id=rd.id AND f.ticket_id=rd.ticket_id WHERE rd.ticket_id=? ORDER BY rd.round_no LIMIT ? OFFSET ?",id,p[1],(p[0]-1)*p[1]);return Map.of("items",list.stream().map(m->metaView(m,selectedRow(row,m.get("id").toString()),m.get("id").equals(row.get("round_id")))).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_round WHERE ticket_id=?",Long.class,id),"page",p[0],"size",p[1]);}
 @GetMapping("/api/ticket/tickets/{id}/rounds/{round}") Map<String,Object> detail(@PathVariable String id,@PathVariable String round,HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw Tickets.bad();var a=t.actor(r,false);var current=t.accessible(id,a);var row=selectedRow(current,Tickets.uuid(round));var out=t.detailView(row,a);project(out,row,current.get("round_id"));if(!row.get("round_id").equals(current.get("round_id"))){out.put("allowedActions",List.of());out.put("currentReopen",null);}return out;}
}
